mapper.sql:
WHERE company_id = #{companyId}
  AND bid_notice_id = #{noticeId}
  AND deleted_at IS NULL
  AND (requested_by = #{userId} OR confirmed = TRUE)

mapper.select:
SELECT bid_notice_summary_id
FROM bid_notice_summary
WHERE company_id = #{companyId}
  AND bid_notice_id = #{noticeId}
  AND requested_by = #{userId}
  AND deleted_at IS NULL
ORDER BY created_at DESC, bid_notice_summary_id DESC
LIMIT 1
